package com.ping.reward;
import java.util.*;import java.util.concurrent.*;
import com.ping.event.*;import com.ping.participant.*;import com.ping.web.*;
import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.test.context.ActiveProfiles;
import static org.assertj.core.api.Assertions.*;
@SpringBootTest(properties="spring.datasource.url=jdbc:h2:mem:eventbenefit;MODE=MySQL;DB_CLOSE_DELAY=-1") @ActiveProfiles("test")
class EventBenefitTests {
 @Autowired BenefitAdminService admin;@Autowired RewardService rewards;@Autowired EventService events;@Autowired ParticipantService people;@Autowired JdbcTemplate sql;
 long event,other,a,benefit;
 @BeforeEach void setup(){sql.update("delete from participants");sql.update("delete from events");event=event("Uno");other=event("Otro");ParticipantForm p=new ParticipantForm();p.setAlias("Lina");p.setEventId(event);a=people.create(p).id();sql.update("update participants set points=80 where id=?",a);benefit=admin.save(event,null,form());}
 long event(String name){EventForm f=new EventForm();f.setName(name);long e=events.create(f).getId();events.transition(e,EventStatus.OPEN);return e;}
 BenefitForm form(){BenefitForm f=new BenefitForm();f.setName("Recuerdo del evento");f.setDescription("Un recuerdo de la actividad");f.setPointsCost(30);f.setClaimLocation("Mesa amarilla");f.setClaimInstructions("Presenta la solicitud al staff.");return f;}
 @Test void catalogAndRequestsAreEventScopedAndDemoRemains(){assertThat(rewards.catalog(event).getFirst().getId()).isEqualTo(benefit);assertThat(rewards.catalog(event)).extracting(Benefit::getName).contains("Recuerdo del evento","Snack del evento · DEMO");assertThat(rewards.catalog(other)).extracting(Benefit::getId).doesNotContain(benefit);long foreign=admin.save(other,null,form());assertThatThrownBy(()->rewards.request(a,foreign,UUID.randomUUID().toString())).isInstanceOf(NotFoundException.class);assertThat(people.get(a).points()).isEqualTo(80);assertThatThrownBy(()->admin.form(other,benefit)).isInstanceOf(NotFoundException.class);}
 @Test void editAndDeactivatePreserveIssuedClaimAndIdempotencyAndDelivery(){String key=UUID.randomUUID().toString();long claim=rewards.request(a,benefit,key);var stale=admin.form(event,benefit);var edit=admin.form(event,benefit);edit.setName("Nuevo nombre");edit.setPointsCost(50);edit.setClaimLocation("Otro lugar");edit.setClaimInstructions("Otras indicaciones");edit.setActive(false);admin.save(event,benefit,edit);
  assertThat(rewards.request(a,benefit,key)).isEqualTo(claim);assertThat(people.get(a).points()).isEqualTo(50);var saved=rewards.personal(a).getFirst();assertThat(saved.benefit()).isEqualTo("Recuerdo del evento");assertThat(saved.cost()).isEqualTo(30);assertThat(saved.claimLocation()).isEqualTo("Mesa amarilla");assertThat(saved.claimInstructions()).isEqualTo("Presenta la solicitud al staff.");assertThatThrownBy(()->rewards.request(a,benefit,UUID.randomUUID().toString())).isInstanceOf(BusinessRuleException.class);assertThatThrownBy(()->admin.save(event,benefit,stale)).isInstanceOf(BusinessRuleException.class);rewards.finish(claim,ClaimStatus.DELIVERED);rewards.finish(claim,ClaimStatus.DELIVERED);assertThat(rewards.personal(a).getFirst().status()).isEqualTo(ClaimStatus.DELIVERED);assertThat(people.get(a).points()).isEqualTo(50);
 }
 @Test void concurrentSameKeyDebitsOnce()throws Exception{String key=UUID.randomUUID().toString();try(var pool=Executors.newFixedThreadPool(2)){var start=new CountDownLatch(1);Callable<Long> request=()->{start.await();return rewards.request(a,benefit,key);};var first=pool.submit(request);var second=pool.submit(request);start.countDown();assertThat(first.get(10,TimeUnit.SECONDS)).isEqualTo(second.get(10,TimeUnit.SECONDS));}assertThat(people.get(a).points()).isEqualTo(50);assertThat(rewards.personal(a)).hasSize(1);}
 @Test void invalidCostsAndMissingLocationAreRejected(){var f=form();f.setPointsCost(0);assertThatThrownBy(()->admin.save(event,null,f)).isInstanceOf(jakarta.validation.ConstraintViolationException.class);f.setPointsCost(10001);assertThatThrownBy(()->admin.save(event,null,f)).isInstanceOf(jakarta.validation.ConstraintViolationException.class);f.setPointsCost(20);f.setClaimLocation("");assertThatThrownBy(()->admin.save(event,null,f)).isInstanceOf(jakarta.validation.ConstraintViolationException.class);assertThat(admin.list(event)).hasSize(1);}
}
